def prefill(entries, lang: str) -> int:
    """일치하는 항목의 ``lang`` 번역이 비었거나 기계번역이면 사전 번역으로 채웁니다."""
    if not lang.lower().startswith("ko"):
        return 0
    n = 0
    for e in entries:
        ko = KO.get(e.text)
        if ko and (not e.translations.get(lang) or lang in e.machine):
            e.translations[lang] = ko
            if lang in e.machine:
                e.machine.remove(lang)
            n += 1
    return n
